public with sharing class ContactDomainService {
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        final Map<String, List<Contact>> result = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return result;
        }

        final List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :accountIds
              AND Email != null
        ];

        for (Contact contactRecord : contacts) {
            final String email = contactRecord.Email;

            if (String.isBlank(email)) {
                continue;
            }

            final Integer atIndex = email.indexOf('@');

            if (atIndex <= 0 || atIndex == email.length() - 1) {
                continue;
            }

            final String domain = email.substring(atIndex + 1).trim().toLowerCase();

            if (String.isBlank(domain)) {
                continue;
            }

            List<Contact> domainContacts = result.get(domain);

            if (domainContacts == null) {
                domainContacts = new List<Contact>();
                result.put(domain, domainContacts);
            }

            domainContacts.add(contactRecord);
        }

        return result;
    }
}
