/**
 * Apex Invocable action that lets a Flow look up a Contact by email address.
 *
 *  • One SOQL query per invocation (bulk-safe up to 200 Flow interviews).
 *  • Email matching is case-insensitive; leading/trailing whitespace in the
 *    input is trimmed before comparison.
 *  • When multiple Contacts share the same email the one with the earliest
 *    CreatedDate is returned.
 *  • Runs under the running user's sharing rules (with sharing).
 */
public with sharing class ContactLookupAction {

    // ──────────────────────────────────────────────────────────────────────────
    //  Inner data classes used by Flow
    // ──────────────────────────────────────────────────────────────────────────

    /**
     * Input variable wrapper – one instance per Flow interview.
     */
    public class Request {
        @InvocableVariable(label='Email' required=true
                           description='The email address to search for')
        public String email;
    }

    /**
     * Output variable wrapper – one instance per Flow interview.
     */
    public class Result {
        @InvocableVariable(label='Contact ID'
                           description='Id of the matching Contact (null when not found)')
        public Id contactId;

        @InvocableVariable(label='Found'
                           description='True when a Contact was matched')
        public Boolean found;
    }

    // ──────────────────────────────────────────────────────────────────────────
    //  Invocable method
    // ──────────────────────────────────────────────────────────────────────────

    @InvocableMethod(label='Find Contact by Email'
                     description='Looks up a Contact whose Email matches the supplied value (case-insensitive, trimmed). Returns the oldest match.'
                     category='CRM')
    public static List<Result> find(List<Request> requests) {

        // ── 1. Collect distinct, trimmed emails for a single SOQL query ──────
        Set<String> emailKeys = new Set<String>();
        for (Request req : requests) {
            String e = req.email;
            if (e == null) {
                continue;
            }
            e = e.trim();
            if (e.isEmpty()) {
                continue;
            }
            // Normalise to lowercase so our in-memory map keys are consistent
            emailKeys.add(e.toLowerCase());
        }

        // ── 2. Single SOQL query (skip entirely when there is nothing to search)
        Map<String, List<Contact>> emailToContacts = new Map<String, List<Contact>>();

        if (!emailKeys.isEmpty()) {
            // SOQL text comparisons are already case-insensitive, but we still
            // use the lowercase form as a map key for the in-memory lookup below.
            List<Contact> contacts = [
                SELECT Id, Email, CreatedDate
                FROM   Contact
                WHERE  Email IN :emailKeys
                ORDER  BY CreatedDate ASC   // earliest first within each group
            ];

            for (Contact c : contacts) {
                String key = c.Email.toLowerCase();
                if (!emailToContacts.containsKey(key)) {
                    emailToContacts.put(key, new List<Contact>());
                }
                emailToContacts.get(key).add(c);
            }
        }

        // ── 3. Build one Result per Request, preserving input order ──────────
        List<Result> results = new List<Result>();

        for (Request req : requests) {
            Result r = new Result();
            r.found     = false;
            r.contactId = null;

            String email = req.email;

            if (email != null) {
                email = email.trim();
            }

            if (email != null && !email.isEmpty()) {
                String lookupKey = email.toLowerCase();
                List<Contact> matches = emailToContacts.get(lookupKey);

                if (matches != null && !matches.isEmpty()) {
                    // contacts came back ordered by CreatedDate ASC, but guard
                    // against unexpected ordering by scanning for the earliest.
                    Contact earliest = matches[0];
                    for (Integer i = 1; i < matches.size(); i++) {
                        if (matches[i].CreatedDate < earliest.CreatedDate) {
                            earliest = matches[i];
                        }
                    }
                    r.found     = true;
                    r.contactId = earliest.Id;
                }
            }

            results.add(r);
        }

        return results;
    }
}
