public with sharing class LeadImportService {

    public class ImportResult {
        public Integer successCount;
        public List<Id> insertedIds;
        public Map<Integer, String> errorsByIndex;

        public ImportResult() {
            this.successCount = 0;
            this.insertedIds = new List<Id>();
            this.errorsByIndex = new Map<Integer, String>();
        }
    }

    public static ImportResult importLeads(List<Lead> leads) {
        ImportResult result = new ImportResult();

        if (leads == null || leads.isEmpty()) {
            return result;
        }

        // Phase 1: identify duplicates by trimmed, lower-cased email
        Set<String> seenEmails = new Set<String>();
        List<Lead> toInsert = new List<Lead>();
        List<Integer> toInsertOrigIndex = new List<Integer>();

        for (Integer i = 0; i < leads.size(); i++) {
            Lead l = leads[i];

            if (l == null) {
                result.errorsByIndex.put(i, 'Lead record is null');
                continue;
            }

            String rawEmail = l.Email;

            if (String.isNotBlank(rawEmail)) {
                String normEmail = rawEmail.trim().toLowerCase();
                if (seenEmails.contains(normEmail)) {
                    result.errorsByIndex.put(i, 'Duplicate email in import: ' + normEmail);
                    continue;
                }
                seenEmails.add(normEmail);
            }

            // Default LeadSource
            if (String.isBlank(l.LeadSource)) {
                l.LeadSource = 'Web';
            }

            toInsert.add(l);
            toInsertOrigIndex.add(i);
        }

        if (toInsert.isEmpty()) {
            return result;
        }

        // Phase 2: single DML, partial success, USER_MODE to respect sharing
        Database.DmlOptions opts = new Database.DmlOptions(false);
        opts.setAccessLevel(AccessLevel.USER_MODE);
        List<Database.SaveResult> saveResults = Database.insert(toInsert, opts);

        // Phase 3: process results
        for (Integer j = 0; j < saveResults.size(); j++) {
            Database.SaveResult sr = saveResults[j];
            Integer originalIndex = toInsertOrigIndex[j];

            if (sr.isSuccess()) {
                result.insertedIds.add(sr.getId());
                result.successCount++;
            } else {
                List<String> messages = new List<String>();
                for (Database.Error err : sr.getErrors()) {
                    messages.add(err.getMessage());
                }
                result.errorsByIndex.put(originalIndex, String.join(messages, '; '));
            }
        }

        return result;
    }
}
