public with sharing class ErpSyncFinalizer implements System.Finalizer {
    private final Set<Id> accountIds;
    private final Integer attempt;

    public ErpSyncFinalizer(Set<Id> accountIds, Integer attempt) {
        this.accountIds = accountIds;
        this.attempt = attempt;
    }

    public void execute(System.FinalizerContext context) {
        FB_Job_Log__c log = new FB_Job_Log__c();
        log.Job_Name__c = 'ErpAccountSyncJob';
        log.Attempt__c = attempt;

        if (context.isSuccess()) {
            log.Status__c = 'Success';
        } else {
            log.Status__c = 'Failed';

            String msg = '';
            Object result = context.getResult();
            if (result instanceof Exception) {
                msg = ((Exception) result).getMessage();
            } else if (result != null) {
                msg = result.toString();
            }
            if (msg == null) {
                msg = '';
            }
            if (msg.length() > 255) {
                msg = msg.substring(0, 255);
            }
            log.Error__c = msg;

            if (attempt < 3) {
                System.enqueueJob(new ErpAccountSyncJob(accountIds, attempt + 1));
            }
        }

        insert log;
    }
}
