/**
 * Pure unit test for RenewalService using ApexMocks (fflib-apex-mocks).
 * No DML and no SOQL. Selector and UnitOfWork are mocked and injected
 * via Application.Selector.setMock / Application.UnitOfWork.setMock.
 *
 * Because the service creates records that never receive real Ids, we
 * inspect the arguments actually passed to the mocked unit of work.
 */
@IsTest
private class RenewalServiceTest {

    /**
     * Build a new, pristine fflib_ApexMocks instance and wire in mocks for
     * the selector and the unit of work. Returns the mocks instance so the
     * caller can stub and verify against it.
     */
    private static fflib_ApexMocks createMocks() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();

        // Mock the selector + inject it
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        Application.Selector.setMock(mockSelector);

        // Mock the unit of work + inject it
        fflib_ISObjectUnitOfWork mockUow =
            (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);
        Application.UnitOfWork.setMock(mockUow);

        return mocks;
    }

    /**
     * Stub selector.selectById(...) to return the provided opportunities.
     */
    private static void stubSelector(
        fflib_ApexMocks mocks,
        IOpportunitiesSelector mockSelector,
        List<Opportunity> results) {

        mocks.startStubbing();
        mocks.when(mockSelector.selectById((Set<Id>) mocks.any(Set<Id>.class)))
             .thenReturn(results);
        mocks.stopStubbing();
    }

    /**
     * Test 1: Only "Closed Won" opportunities (with a CloseDate) get a renewal.
     * A "Prospecting" opportunity and one without a CloseDate must be skipped
     * and must NOT result in any unit-of-work calls or commitWork().
     */
    @IsTest
    static void createRenewals_onlyClosedWonAreRenewed() {
        fflib_ApexMocks mocks = createMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) Application.Selector.getInstance(Opportunity.SObjectType);
        fflib_ISObjectUnitOfWork mockUow =
            (fflib_ISObjectUnitOfWork) Application.UnitOfWork.newInstance();

        // --- GIVEN: a mixed list of opportunities ---
        Id accId = fflib_IDGenerator.generate(Account.SObjectType);
        Id ownerId = fflib_IDGenerator.generate(User.SObjectType);

        Opportunity closedWon = new Opportunity(
            Name = 'Won Deal',
            AccountId = accId,
            OwnerId = ownerId,
            StageName = 'Closed Won',
            CloseDate = Date.newInstance(2024, 6, 1),
            Amount = 100.00
        );
        // Different account/owner so we can prove they are NOT used for renewal
        Opportunity prospecting = new Opportunity(
            Name = 'Open Deal',
            AccountId = fflib_IDGenerator.generate(Account.SObjectType),
            OwnerId = fflib_IDGenerator.generate(User.SObjectType),
            StageName = 'Prospecting',
            CloseDate = Date.newInstance(2024, 7, 1),
            Amount = 200.00
        );
        Opportunity wonButNoCloseDate = new Opportunity(
            Name = 'No Close Date',
            AccountId = accId,
            OwnerId = ownerId,
            StageName = 'Closed Won',
            CloseDate = null,
            Amount = 300.00
        );

        stubSelector(
            mocks,
            mockSelector,
            new List<Opportunity>{ closedWon, prospecting, wonButNoCloseDate }
        );

        // --- WHEN ---
        RenewalService.createRenewals(
            new Set<Id>{ (Id) closedWon.Id }
        );

        // --- THEN ---
        // Only 2 calls to the unit of work: registerNew(renewal) + registerNew(task, ...).
        // Only the Closed Won opportunity should have triggered work.
        Integer totalRegisterNew = 0;
        for (Object call : mocks.getCalls(fflib_ISObjectUnitOfWork.class, 'registerNew', 1)) {
            if (call instanceof SObject) {
                SObject obj = (SObject) call;
                if (obj.get('Name') != null && !obj.get('Name').startsWith('Prepare renewal for')) {
                    totalRegisterNew++;
                }
            }
        }

        // Exactly 1 renewal opportunity + 1 task registered.
        // We just check commitWork was called and nothing else.
        // The task will check the specific fields below.
        verify(mockUow, 1).commitWork();

        // Count registerNew calls that pass an Opportunity (the renewals)
        Integer renewalCount = 0;
        Integer taskCount = 0;
        for (Object[] args : mocks.getCapturedArguments(
                fflib_ISObjectUnitOfWork.class, 'registerNew')) {
            if (args[0] instanceof Opportunity && args.length == 1) {
                renewalCount++;
            } else if (args[0] instanceof Task) {
                taskCount++;
            }
        }
        Assert.areEqual(1, renewalCount, 'Should create exactly 1 renewal');
        Assert.areEqual(1, taskCount, 'Should create exactly 1 task');
    }

    /**
     * Test 2: Full happy path — verify every field on the renewal Opportunity,
     * the reminder Task, and that commitWork() is called once.
     */
    @IsTest
    static void createRenewals_setsCorrectFieldsAndCommitWork() {
        fflib_ApexMocks mocks = createMocks();
        IOpportunitiesSelector mockSelector =
            (IOpportunitiesSelector) Application.Selector.getInstance(Opportunity.SObjectType);
        fflib_ISObjectUnitOfWork mockUow =
            (fflib_ISObjectUnitOfWork) Application.UnitOfWork.newInstance();

        // --- GIVEN ---
        Date originalCloseDate = Date.newInstance(2024, 3, 15);
        Id originalAccountId = fflib_IDGenerator.generate(Account.SObjectType);
        Id originalOwnerId = fflib_IDGenerator.generate(User.SObjectType);

        Opportunity original = new Opportunity(
            Name = 'Acme Renewal Target',
            AccountId = originalAccountId,
            OwnerId = originalOwnerId,
            StageName = 'Closed Won',
            CloseDate = originalCloseDate,
            Amount = 200.00
        );

        stubSelector(mocks, mockSelector, new List<Opportunity>{ original });

        // --- WHEN ---
        RenewalService.createRenewals(new Set<Id>{ (Id) original.Id });

        // --- THEN ---
        // Collect all registerNew calls (both 1-arg and 3-arg variants).
        List<Object[]> registerNewCalls =
            mocks.getCapturedArguments(fflib_ISObjectUnitOfWork.class, 'registerNew');

        // We expect 2 calls: registerNew(renewal) and registerNew(task, WhatId, renewal)
        Assert.areEqual(2, registerNewCalls.size(), 'Expected 2 registerNew calls');

        // Sort into renewal call (single SObject) and task call (3 args).
        Object[] renewalCall = null;
        Object[] taskCall = null;
        for (Object[] args : registerNewCalls) {
            if (args.length == 1 && args[0] instanceof Opportunity) {
                renewalCall = args;
            } else if (args.length == 3 && args[0] instanceof Task) {
                taskCall = args;
            }
        }
        Assert.isNotNull(renewalCall, 'Should have a registerNew(SObject) call for the renewal');
        Assert.isNotNull(taskCall, 'Should have a registerNew(SObject, SObjectField, SObject) call for the task');

        // ---- Verify renewal Opportunity ----
        Opportunity renewal = (Opportunity) renewalCall[0];

        Assert.areEqual('Acme Renewal Target - Renewal', renewal.Name,
            'Renewal Name must append " - Renewal"');

        Assert.areEqual(originalAccountId, renewal.AccountId,
            'Renewal AccountId must match the original');

        Assert.areEqual('Prospecting', renewal.StageName,
            'Renewal StageName must be Prospecting');

        Date expectedCloseDate = originalCloseDate.addYears(1); // 2025-03-15
        Assert.areEqual(expectedCloseDate, renewal.CloseDate,
            'Renewal CloseDate must be original + 1 year');

        // Amount = 200 * 1.05 = 210.00 (exactly 2 decimal places)
        Decimal expectedAmount = (200.00 * RenewalService.UPLIFT).setScale(2);
        Assert.areEqual(expectedAmount, renewal.Amount,
            'Renewal Amount must be original Amount × UPLIFT rounded to 2 decimals');

        // ---- Verify Task ----
        Task reminder = (Task) taskCall[0];

        Assert.areEqual('Prepare renewal for Acme Renewal Target', reminder.Subject,
            'Task Subject must follow "Prepare renewal for <original Name>"');

        Assert.areEqual(originalOwnerId, reminder.OwnerId,
            'Task OwnerId must be the original opportunity owner');

        Date expectedActivityDate = expectedCloseDate.addDays(-60);
        Assert.areEqual(expectedActivityDate, reminder.ActivityDate,
            'Task ActivityDate must be renewal CloseDate minus 60 days');

        // The task must be related to the NEW renewal, not the original.
        // registerNew(task, Task.WhatId, parentSObject) — the third argument is the parent.
        Assert.areEqual(renewal, taskCall[2],
            'Task must be registered against the new renewal, not the original opportunity');

        // ---- Verify commitWork ----
        verify(mockUow, 1).commitWork();
    }

    /**
     * Test 3: Null or empty opportunityIds — no UoW work and no commit.
     */
    @IsTest
    static void createRenewals_nullOrEmptyInputDoesNothing() {
        fflib_ApexMocks mocks = createMocks();
        fflib_ISObjectUnitOfWork mockUow =
            (fflib_ISObjectUnitOfWork) Application.UnitOfWork.newInstance();

        RenewalService.createRenewals(null);
        RenewalService.createRenewals(new Set<Id>());

        // No registerNew calls at all.
        Assert.areEqual(0,
            mocks.getCapturedArguments(fflib_ISObjectUnitOfWork.class, 'registerNew').size(),
            'No registerNew calls expected for null/empty input');
    }
}
