@IsTest
private class InvoicingServiceTest {

    // ──────────────────────────────────────────────────────────────────────────
    // Helper: create a mock set and inject them into the Application factories
    // ──────────────────────────────────────────────────────────────────────────
    private class Mocks {
        final fflib_ApexMocks apexMocks = new fflib_ApexMocks();
        final IBillingGateway gateway;
        final IOpportunitiesSelector selector;
        final fflib_ISObjectUnitOfWork uow;

        Mocks() {
            gateway  = (IBillingGateway) apexMocks.mock(IBillingGateway.class);
            selector = (IOpportunitiesSelector) apexMocks.mock(IOpportunitiesSelector.class);
            uow      = (fflib_ISObjectUnitOfWork) apexMocks.mock(fflib_ISObjectUnitOfWork.class);

            Application.Service.setMock(IBillingGateway.class, gateway);
            Application.Selector.setMock(Opportunity.SObjectType, selector);
            Application.UnitOfWork.setMock(uow);
        }
    }

    private Opportunity buildOpp(Id oppId, Id accountId, String stage, Decimal amount) {
        return new Opportunity(
            Id        = oppId,
            Name      = 'Test-' + oppId,
            AccountId = accountId,
            StageName = stage,
            Amount    = amount
        );
    }

    // ──────────────────────────────────────────────────────────────────────────
    // 1. Authentication failure → InvoicingException, no invoicing at all
    // ──────────────────────────────────────────────────────────────────────────
    @IsTest
    static void authenticateThrows_BillingException_Throws_InvoicingException() {
        Mocks m = new Mocks();

        // Stub authenticate to throw
        m.apexMocks.startStubbing();
        ((IBillingGateway) m.gateway).authenticate();
        m.apexMocks.thenThrow(new BillingException('Gateway unreachable'));
        m.apexMocks.stopStubbing();

        Id oppId = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Set<Id> oppIds = new Set<Id>{ oppId };

        // Act
        InvoicingService.InvoicingException caught = null;
        try {
            InvoicingService.invoiceWonOpportunities(oppIds);
        } catch (InvoicingService.InvoicingException e) {
            caught = e;
        }

        // Assert
        System.assertNotEquals(null, caught, 'Expected InvoicingException');
        System.assert(
            caught.getMessage().contains('Gateway unreachable'),
            'Message should contain gateway error: ' + caught.getMessage()
        );

        // Verify nothing was invoiced, registered, or committed
        m.apexMocks.startVerification();
        ((IBillingGateway) m.gateway).createInvoice(
            (Id) fflib_ApexMocks.any(Id.class), (Decimal) fflib_ApexMocks.any(Decimal.class)
        );
        m.apexMocks.verify(m.gateway, (Integer) 0).createInvoice(
            (Id) fflib_ApexMocks.any(Id.class), (Decimal) fflib_ApexMocks.any(Decimal.class)
        );
        ((fflib_ISObjectUnitOfWork) m.uow).registerDirty((SObject) fflib_ApexMocks.any(SObject.class));
        m.apexMocks.verify(m.uow, (Integer) 0).registerDirty((SObject) fflib_ApexMocks.any(SObject.class));
        ((fflib_ISObjectUnitOfWork) m.uow).commitWork();
        m.apexMocks.verify(m.uow, (Integer) 0).commitWork();
        m.apexMocks.stopVerification();
    }

