/**
 * Central wiring class for the fflib (Financial Force Lightning) framework.
 * All service, selector, domain, and unit-of-work objects are resolved through
 * these four static factories so that test code can swap in mocks via setMock().
 */
public with sharing class Application {

    // ─── Unit of Work ────────────────────────────────────────────────────────────
    //
    //   Supports insert ordering: Account → Contact → Opportunity → OpportunityContactRole.
    //   Relationships allow a single commitWork() to insert a new Account, its Contacts,
    //   its Opportunities, and OCR join records with correct parent-first ordering.
    //
    public static final fflib_Application.UnitOfWorkFactory UnitOfWork =
        new fflib_SObjectUnitOfWork(
            new List<fflib_SObjectUnitOfWork.IDFactory>{
                new fflib_SObjectUnitOfWork.IDFactory(Account.SObjectType),
                new fflib_SObjectUnitOfWork.IDFactory(Contact.SObjectType),
                new fflib_SObjectUnitOfWork.IDFactory(Opportunity.SObjectType),
                new fflib_SObjectUnitOfWork.IDFactory(OpportunityContactRole.SObjectType)
            },
            new List<fflib_SObjectUnitOfWork.SObjectRelationship>{
                new fflib_SObjectUnitOfWork.SObjectRelationship(
                    Contact.SObjectType,          Contact.AccountId,
                    Account.SObjectType,          Account.Id
                ),
                new fflib_SObjectUnitOfWork.SObjectRelationship(
                    Opportunity.SObjectType,      Opportunity.AccountId,
                    Account.SObjectType,          Account.Id
                ),
                new fflib_SObjectUnitOfWork.SObjectRelationship(
                    OpportunityContactRole.SObjectType, OpportunityContactRole.ContactId,
                    Contact.SObjectType,          Contact.Id
                ),
                new fflib_SObjectUnitOfWork.SObjectRelationship(
                    OpportunityContactRole.SObjectType, OpportunityContactRole.OpportunityId,
                    Opportunity.SObjectType,      Opportunity.Id
                )
            }
        );

    // ─── Service ─────────────────────────────────────────────────────────────────
    //
    //   Resolves IAccountsService → AccountsServiceImpl for Account SObject type.
    //
    public static final fflib_Application.ServiceFactory Service =
        new fflib_Application.ServiceFactory(
            new Map<Schema.SObjectType, Map<Type, Type>>{
                Account.SObjectType => new Map<Type, Type>{
