/**
 * Domain class for Opportunity records following Apex Enterprise Patterns (fflib).
 *
 * • Defaults CloseDate to today + 30 days when not supplied (insert only).
 * • Defaults Type to 'New Customer' when not supplied (insert only).
 * • Existing values are never overwritten.
 */
public class Opportunities extends fflib_SObjectDomain {

    // -----------------------------------------------------------------------
    // Constructor – required by fflib_SObjectDomain.triggerHandler
    // -----------------------------------------------------------------------
    public Opportunities(List<Opportunity> records) {
        super(records);
    }

    /**
     * Inner class that lets the fflib framework instantiate the domain
     * from a generic List&lt;SObject&gt;.
     */
    public class Constructor implements fflib_SObjectDomain.IConstructable {
        public fflib_SObjectDomain construct(List<SObject> records) {
            return new Opportunities(records);
        }
    }

    // -----------------------------------------------------------------------
    // Before insert – apply defaults
    // -----------------------------------------------------------------------
    public override void beforeInsert() {
        for (Opportunity opp : (List<Opportunity>) records) {
            if (opp.CloseDate == null) {
                opp.CloseDate = Date.today().addDays(30);
            }
            if (String.isBlank(opp.Type)) {
                opp.Type = 'New Customer';
            }
        }
    }
}
