public with sharing class AccountOnboardingService {

    public static List<Account> createAccountsWithContacts(Map<String, List<String>> contactLastNamesByAccountName) {
        List<Account> newAccounts = new List<Account>();

        if (contactLastNamesByAccountName == null || contactLastNamesByAccountName.isEmpty()) {
            return newAccounts;
        }

        fflib_SObjectUnitOfWork uow = new fflib_SObjectUnitOfWork(
            new List<Schema.SObjectType>{
                Account.SObjectType,
                Contact.SObjectType
            }
        );

        Schema.SObjectField contactAccountIdField = Schema.SObjectType.Contact.fields.AccountId;

        for (String accountName : contactLastNamesByAccountName.keySet()) {

            Account acct = new Account(Name = accountName);
            uow.registerDirty(acct);
            newAccounts.add(acct);

            List<String> lastNames = contactLastNamesByAccountName.get(accountName);
            if (lastNames == null || lastNames.isEmpty()) {
                continue;
            }

            for (String lastName : lastNames) {
                Contact con = new Contact(LastName = lastName);
                // registerRelationship internally calls registerDirty on both parent and child,
                // and after inserting parents, sets Contact.AccountId to the new Account Id
                // before inserting Contacts – all within a single bulk DML.
                uow.registerRelationship(acct, con, contactAccountIdField);
            }
        }

        uow.commitWork();

        return newAccounts;
    }
}
